#Region @DOC
#### Description:
#Runs a TI process on another database over the REST API (`tm1.ExecuteWithReturn`). If the process does not exist on the target database, it is first copied from the source database with `}bedrock.migrate.process`.
#
#### How to Use:
#
#- `pProcess`: REQUIRED: the name of the process to run.
#- `pProcessParameters`: OPTIONAL: a JSON Object of parameter values for the process, e.g. `{"pCube": "Sales", "pLogOutput": 1}`. Any other value that isn't blank is an error.
#- `pTargetConnectionName`: OPTIONAL: the database the process runs on.
#- `pSourceConnectionName`: OPTIONAL: the database the process is copied from if it does not exist on the target.
#- Both are connection names, or connection-details JSON objects. A blank name means this database.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes. Connection-details objects are logged as their URL only.
#
#### Return Value:
#`sBedrockReturnValue` is set to the `ExecuteWithReturn` response, with `/body/ErrorLogFile` simplified to the error log file name.
#
#An error is added, so `pStrictErrorHandling` = 1 ends with `ProcessQuit`, when:
#- a session cannot be started on the source or target database (nothing is run);
#- the process is missing on the target and `}bedrock.migrate.process` fails to copy it (the process is not run, and `sBedrockReturnValue` is `''`). With `pStrictErrorHandling` = 0, a process that exists on neither database is not a failed copy: the run goes on, `ExecuteWithReturn` answers 404, and `sBedrockReturnValue` holds that response;
#- `ExecuteWithReturn` returns a non-2xx status or no `ProcessExecuteStatusCode`;
#- the remote process ends with `ProcessExecuteStatusCode` `QuitCalled` or `Aborted`.
#
#`HasMinorErrors` is only logged.
#
#Here is an example call:
#```
#ExecuteProcess( '}bedrock.process.execute_externally',
#  'pProcess', '}bedrock.cube.data.clear',
#  'pProcessParameters', '{"pCube": "Sales"}',
#  'pSourceConnectionName', 'Development',
#  'pTargetConnectionName', 'UAT' );
#```
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pProcess":             null,
  "pProcessParameters":   "",
  "pSourceConnectionName":  null,
  "pTargetConnectionName":  null,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pProcess":             '|StringToJson  ( pProcess             )|',
  "pProcessParameters":   '|StringToJson  ( pProcessParameters   )|',
  "pSourceConnectionName":  '|StringToJson  ( pSourceConnectionName  )|',
  "pTargetConnectionName":  '|StringToJson  ( pTargetConnectionName  )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pProcess             =                 JsonToString( pJson, '/pProcess'             );
IF( JsonType( JsonGet( pJson, '/pProcessParameters' ) ) @= 'string' );
  pProcessParameters = JsonToString( pJson, '/pProcessParameters' );
ELSE;
  pProcessParameters = JsonGet( pJson, '/pProcessParameters' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pSourceConnectionName' ) ) @= 'string' );
  pSourceConnectionName = JsonToString( pJson, '/pSourceConnectionName' );
ELSE;
  pSourceConnectionName = JsonGet( pJson, '/pSourceConnectionName' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pTargetConnectionName' ) ) @= 'string' );
  pTargetConnectionName = JsonToString( pJson, '/pTargetConnectionName' );
ELSE;
  pTargetConnectionName = JsonGet( pJson, '/pTargetConnectionName' );
ENDIF;
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

### Connection-details objects are logged as their URL only
IF( JsonType( pSourceConnectionName ) @= 'object' );
  pPassedParameters = JsonReplace( pPassedParameters, '/pSourceConnectionName', StringToJson( JsonToString( pSourceConnectionName, '/sURL' ) ) );
ENDIF;
IF( JsonType( pTargetConnectionName ) @= 'object' );
  pPassedParameters = JsonReplace( pPassedParameters, '/pTargetConnectionName', StringToJson( JsonToString( pTargetConnectionName, '/sURL' ) ) );
ENDIF;
IF( JsonType( pProcessParameters ) @= 'object' );
  IF( JsonType( JsonGet( pProcessParameters, '/pJson' ) ) @<> '' );
    pPassedParameters = JsonReplace( pPassedParameters, '/pProcessParameters', JsonReplace( pProcessParameters, '/pJson', '"***"' ) );
  ENDIF;
ENDIF;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################
#################################################################################################
#Region - Validate Parameters

IF( pProcess @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pProcess is required."' );
ENDIF;
IF( pProcessParameters @<> '' & JsonType( pProcessParameters ) @<> 'object' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pProcessParameters must be blank or a JSON object."' );
ENDIF;

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceConnectionName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pSourceConnectionName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pSourceConnectionName', sSourceConnectionDetails );

sTargetDatabaseParameterType = JsonType( pTargetConnectionName );
IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pTargetConnectionName, 'pJson', pJson ); sTargetConnectionDetails = sBedrockReturnValue;
ELSE;
  sTargetConnectionDetails = pTargetConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pTargetConnectionName', sTargetConnectionDetails );

sSourceURL = JsonToString( sSourceConnectionDetails, '/sURL' );
sTargetURL = JsonToString( sTargetConnectionDetails, '/sURL' );

### Authentication headers for requests to the source connection
sSrcAuthHeaders = '[]';
IF( JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sSourceConnectionDetails, '/sSID' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sSourceConnectionDetails, '/sSID' ) ) );
ENDIF;

### Authentication headers for requests to the target connection
sTgtAuthHeaders = '[]';
IF( JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sTargetConnectionDetails, '/sSID' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sTargetConnectionDetails, '/sSID' ) ) );
ENDIF;

### A blank URL would send every request to this database
IF( sSourceURL @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"Could not start a session on the source database."' );
ENDIF;
IF( sTargetURL @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"Could not start a session on the target database."' );
ENDIF;

#EndRegion - Validate Parameters

#Region - Execute Process Remotely

IF( JsonSize( sMessages, '/Error' ) = 0 );
  # Check if the process exists on the target. pJson is not forwarded here, so that a 404 is
  # not treated as an error when pStrictErrorHandling = 1.
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',    'GET',
    'pURL',       sTargetURL | '/Processes(''' | URLEncode( pProcess ) | ''')?$select=Name',
    'pHeaders',   sTgtAuthHeaders,
    'pLogOutput', pLogOutput
  );
  nStatusCode = StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) );

  # If the process doesn't exist on the target, copy it from the source
  IF( nStatusCode = 404 );
    nExit = ExecuteProcess( '}bedrock.migrate.process',
      'pProcess',               pProcess,
      'pSourceConnectionName',    sSourceConnectionDetails,
      'pTargetConnectionName',    sTargetConnectionDetails,
      'pIncludeControlObjects', 1,
      'pLogOutput',             pLogOutput,
      'pStrictErrorHandling',   pStrictErrorHandling
    );
    IF( nExit <> ProcessExitNormal() );
      sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Could not copy process ''' | pProcess | ''' from the source database to the target database.' ) );
    ENDIF;
  ENDIF;
ENDIF;

sResponse = '';
IF( JsonSize( sMessages, '/Error' ) = 0 );
  # Reshape pProcessParameters for tm1.ExecuteWithReturn
  sReshapedParameters = IF( JsonSize( pProcessParameters ) > 0, '{"Parameters":[]}', '' );
  WHILE( JsonSize( pProcessParameters ) > 0 );
    sKey = JsonGetKey( pProcessParameters, 0 );
    sReshapedParameters = JsonAdd( sReshapedParameters, '/Parameters/0', '{"Name": '|StringToJson( sKey )|', "Value": '|JsonGet( pProcessParameters, sKey )|'}' );
    pProcessParameters = JsonRemove( pProcessParameters, sKey );
  END;

  # Execute the process on the target database
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',  'POST',
    'pURL',     sTargetURL | '/Processes(''' | URLEncode( pProcess ) | ''')/tm1.ExecuteWithReturn?$expand=*',
    'pBody',    sReshapedParameters,
    'pHeaders', JsonAdd( sTgtAuthHeaders, '', '"Accept: application/json;odata.metadata=none"' ),
    'pJson',    pJson
  );
  sResponse = sBedrockReturnValue;

  # Simplify ErrorLogFile to just its file name, when there is one
  IF( JsonType( JsonGet( sResponse, '/body/ErrorLogFile' ) ) @= 'object' );
    sResponse = JsonPatch( sResponse, '[{"op": "move", "from": "/body/ErrorLogFile/Filename", "path": "/body/ErrorLogFile"}]' );
  ENDIF;

  nStatusCode = StringToNumber( JsonToString( sResponse, '/status_code' ) );
  IF( nStatusCode < 200 % nStatusCode >= 300 % JsonType( JsonGet( sResponse, '/body/ProcessExecuteStatusCode' ) ) @<> 'string' );
    sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Could not run process ''' | pProcess | ''' on the target database (HTTP status ' | NumberToString( nStatusCode ) | ').' ) );
  ENDIF;
ENDIF;

#EndRegion - Execute Process Remotely

#Region - Cleanup

# Close sessions this process opened
IF( sSourceDatabaseParameterType @<> 'object' & sSourceURL @<> '' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sSourceURL | '/ActiveSession/tm1.Close', 'pHeaders', sSrcAuthHeaders );
ENDIF;
IF( sTargetDatabaseParameterType @<> 'object' & sTargetURL @<> '' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sTargetURL | '/ActiveSession/tm1.Close', 'pHeaders', sTgtAuthHeaders );
ENDIF;

sBedrockReturnValue = sResponse;

#EndRegion - Cleanup

#Region - Check Remote Status

sRemoteStatus = '';
IF( JsonType( JsonGet( sResponse, '/body/ProcessExecuteStatusCode' ) ) @= 'string' );
  sRemoteStatus = JsonToString( sResponse, '/body/ProcessExecuteStatusCode' );
ENDIF;

IF( sRemoteStatus @= 'QuitCalled' % sRemoteStatus @= 'Aborted' );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Process ''' | pProcess | ''' ended with status ' | sRemoteStatus | ' on the target database.' ) );
ELSEIF( sRemoteStatus @= 'HasMinorErrors' & pLogOutput = 1 );
  LogOutput( 'WARN', 'Process ''' | pProcess | ''' ended with minor errors on the target database.' );
ENDIF;

IF( JsonSize( sMessages, '/Error' ) <> 0 );
  LogOutput( 'ERROR', JsonToString( sMessages, '/Error/0' ) );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Check Remote Status
#################################################################################################
